IFL_DATA.register("modeFinder", {"disclaimers":["Educational tool only. It summarises the textbook's discussion of when each mode is typically suitable. It is not a Fatwa, a Shari’ah ruling or financial advice; real transactions must be structured with a qualified Shari’ah board.","Educational tool based on Muhammad Ayub's textbook; not a Shari'ah ruling or professional advice."],"pathways":[{"id":"need","title":"By client need","start":"need","nodes":{"need":{"id":"need","q":"What does the client mainly need?","options":[{"label":"To buy goods / raw materials / an asset","next":"goods"},{"label":"To use an asset without buying it now","next":"use"},{"label":"Finance for a business or project with shared risk","next":"venture"},{"label":"Something manufactured or constructed","next":"build"},{"label":"Cash / liquidity","next":"cash"},{"label":"A service or a result (e.g. debt recovery)","next":"service"}]},"goods":{"id":"goods","q":"When will the goods be delivered?","options":[{"label":"Goods exist now; payment later","next":"goods-now"},{"label":"Goods will be produced later (e.g. crop); seller needs money now","result":"n-salam"}]},"goods-now":{"id":"goods-now","q":"Should the bank disclose its cost?","options":[{"label":"Yes — cost-plus pricing","result":"n-murabaha"},{"label":"No — bargained price","result":"n-musawamah"}]},"use":{"id":"use","q":"Does the client want ownership at the end?","options":[{"label":"No — use only","result":"n-ijarah"},{"label":"Yes — eventually own it","next":"own-end"}]},"own-end":{"id":"own-end","q":"Will the client contribute part of the price up front and buy the rest gradually?","options":[{"label":"Yes — joint ownership, buying units","result":"n-dm"},{"label":"No — lease, then separate transfer","result":"n-imbt"}]},"venture":{"id":"venture","q":"Will the client also contribute capital?","options":[{"label":"Yes — both contribute capital","result":"n-musharakah"},{"label":"No — bank provides capital, client manages","result":"n-mudarabah"}]},"build":{"id":"build","q":"Is the bank financing a customer who ordered the asset?","options":[{"label":"Yes — bank delivers the asset and subcontracts construction","result":"n-parallel-istisna"},{"label":"Buyer orders directly from the manufacturer","result":"n-istisna"}]},"cash":{"id":"cash","q":"Is the client a producer who can sell future output?","options":[{"label":"Yes — sell output in advance","result":"n-salam"},{"label":"No — corporate liquidity need with no other option","result":"n-tawarruq"},{"label":"Government or large corporate with durable assets","result":"n-sukuk"}]},"service":{"id":"service","q":"Is the work and wage specifiable?","options":[{"label":"Yes — defined work for a wage/fee","result":"n-ujrah"},{"label":"No — only the result can be specified","result":"n-jualah"}]}},"origin":"f1"},{"id":"purpose","title":"By financing purpose","start":"q-purpose","nodes":{"q-purpose":{"id":"q-purpose","q":"What is the primary financing purpose?","options":[{"label":"Buying/acquiring a specific existing asset or goods","next":"q-cost-disclosure"},{"label":"Need goods manufactured, constructed, or delivered later against advance finance","next":"q-existing-or-manufactured"},{"label":"Need the use of an asset without owning it outright","next":"q-eventual-ownership"},{"label":"Partnering / investing in a business venture","next":"q-active-management"},{"label":"Acquiring full ownership of a fixed asset gradually (e.g. a house)","result":"r-diminishing-musharakah"},{"label":"Managing liquidity or raising capital-market funds","next":"q-liquidity-or-capital-market"},{"label":"Covering the risk of loss to life or property (insurance-type need)","next":"q-takaful-model"}]},"q-cost-disclosure":{"id":"q-cost-disclosure","q":"Do you want, or need, the seller to disclose the original cost and profit margin added to it?","options":[{"label":"Yes, I want transparent cost-plus pricing","result":"r-murabaha"},{"label":"No, just agree a final bargained price","result":"r-musawamah"}]},"q-existing-or-manufactured":{"id":"q-existing-or-manufactured","q":"Does the item already exist in the market in standard, fungible form, or does it need to be custom manufactured or constructed?","options":[{"label":"It exists in standard, fungible form, and I can pay the full price now for future delivery","result":"r-salam"},{"label":"It needs custom manufacturing or construction, and I may need flexible payment terms","result":"r-istisnaa"}]},"q-eventual-ownership":{"id":"q-eventual-ownership","q":"Do you eventually want to become the owner of the asset at the end of the usage period?","options":[{"label":"No, I just need temporary use of the asset","result":"r-ijarah"},{"label":"Yes, I want to transition to ownership over time","result":"r-ijarah-mbt"}]},"q-active-management":{"id":"q-active-management","q":"Will the financier also actively co-invest and take part in managing the business, or just supply capital while someone else manages?","options":[{"label":"The financier co-invests and may take part in management","next":"q-loss-sharing"},{"label":"The financier supplies capital only; an expert manager (Mudarib) runs the business","result":"r-mudarabah"}]},"q-loss-sharing":{"id":"q-loss-sharing","q":"Will all partners remain full partners throughout, sharing losses strictly in proportion to their capital contribution?","options":[{"label":"Yes, an ongoing full partnership with proportional loss-sharing","result":"r-musharakah"},{"label":"No, we want one partner's ownership share to be periodically bought out by the other","result":"r-diminishing-musharakah"}]},"q-liquidity-or-capital-market":{"id":"q-liquidity-or-capital-market","q":"Are you looking to raise immediate cash for yourself, or to mobilize funds from many investors for a project via tradable certificates?","options":[{"label":"Raise immediate cash for myself or my business","next":"q-liquidity-necessity"},{"label":"Mobilize funds from many investors via tradable certificates for a project","next":"q-sukuk-basis"}]},"q-liquidity-necessity":{"id":"q-liquidity-necessity","q":"Is this an unavoidable, limited corporate liquidity need, or more of a routine/consumer financing want?","options":[{"label":"An unavoidable, limited corporate liquidity need","result":"r-tawarruq"},{"label":"A routine or consumer financing want","result":"r-caution-tawarruq"}]},"q-sukuk-basis":{"id":"q-sukuk-basis","q":"Will the certificates represent undivided ownership in real assets/usufruct/a Shari'ah-compliant project, or a pure interest-bearing debt claim?","options":[{"label":"Undivided ownership in real assets or a project (Ijarah, Salam, Istisna'a or Shirkah basis)","result":"r-sukuk"},{"label":"A pure interest-bearing debt claim with no underlying asset","result":"r-non-compliant-debt"}]},"q-takaful-model":{"id":"q-takaful-model","q":"Do you mainly need Shari'ah-compliant, mutual risk-pooling cover, regardless of whether the operator uses a Mudarabah, Wakalah, or hybrid Wakalah-Mudarabah model?","options":[{"label":"Yes, any recognized model of mutual risk-pooling cover","result":"r-takaful"}]}},"origin":"f2"}],"results":{"n-murabaha":{"id":"n-murabaha","title":"Murabaha (MPO)","why":"Short-term purchase of existing goods at cost plus disclosed profit.","topicIds":["t9.3","t9.8","t14.3.2"],"cautions":["Bank must own and bear risk before sale","No rollover; penalties to charity"],"modeIds":["murabaha"],"pathway":"need","origin":["f1"]},"n-musawamah":{"id":"n-musawamah","title":"Musawamah","why":"Sale of goods at a bargained price without disclosing cost.","topicIds":["t9.11","t9.11.1"],"cautions":["Avoid gross overpricing (Ghaban)"],"modeIds":["musawamah"],"pathway":"need","origin":["f1"]},"n-salam":{"id":"n-salam","title":"Salam","why":"Advance full payment for goods produced later — agriculture and working capital.","topicIds":["t10.2","t10.10","t14.4.1"],"cautions":["Full prepayment","Precise specifications and delivery date"],"modeIds":["salam"],"pathway":"need","origin":["f1"]},"n-ijarah":{"id":"n-ijarah","title":"Ijarah (operating lease)","why":"Use of a non-consumable asset for rent; bank keeps ownership risk.","topicIds":["t11.1","t11.3"],"cautions":["No rent before delivery","Lessor bears major repairs and Takaful"],"modeIds":["ijarah"],"pathway":"need","origin":["f1"]},"n-imbt":{"id":"n-imbt","title":"Ijarah Muntahia-bi-Tamleek","why":"Lease ending in ownership through a separate promise to sell or gift.","topicIds":["t11.5","t11.5.1"],"cautions":["Keep lease and transfer separate"],"modeIds":["ijarah-muntahia-bi-tamleek"],"pathway":"need","origin":["f1"]},"n-dm":{"id":"n-dm","title":"Diminishing Musharakah","why":"Joint ownership with rent on the bank's share and gradual unit purchase — housing and fixed assets.","topicIds":["t12.8","t12.9.2"],"cautions":["Separate contracts","Pre-agreed unit price only in Shirkatulmilk"],"modeIds":["diminishing-musharakah"],"pathway":"need","origin":["f1"]},"n-musharakah":{"id":"n-musharakah","title":"Musharakah","why":"Both contribute capital; profit as agreed, loss by capital.","topicIds":["t12.3","t12.7.2"],"cautions":["No guarantee of capital or profit"],"modeIds":["musharakah"],"pathway":"need","origin":["f1"]},"n-mudarabah":{"id":"n-mudarabah","title":"Mudarabah","why":"Bank supplies capital, client supplies management; loss borne by capital provider.","topicIds":["t12.4","t12.7.2"],"cautions":["Higher moral-hazard risk; monitoring needed"],"modeIds":["mudarabah"],"pathway":"need","origin":["f1"]},"n-istisna":{"id":"n-istisna","title":"Istisna‘a","why":"Order to manufacture/construct with flexible payment.","topicIds":["t10.11","t10.11.3"],"cautions":["Only for manufactured items"],"modeIds":["istisnaa"],"pathway":"need","origin":["f1"]},"n-parallel-istisna":{"id":"n-parallel-istisna","title":"Istisna‘a + Parallel Istisna‘a","why":"Bank sells the asset to the customer and subcontracts construction.","topicIds":["t10.11.7","t14.4.3"],"cautions":["Two independent contracts"],"modeIds":["istisnaa"],"pathway":"need","origin":["f1"]},"n-tawarruq":{"id":"n-tawarruq","title":"Tawarruq (with caution)","why":"Credit purchase and spot sale to a third party — scholars advise only for unavoidable corporate liquidity needs.","topicIds":["t13.3","t13.3.1"],"cautions":["Avoid agency to self and paper-only trades","Qard al Hasan is preferable"],"modeIds":["tawarruq"],"pathway":"need","origin":["f1"]},"n-sukuk":{"id":"n-sukuk","title":"Sukuk","why":"Securitise durable assets (e.g. Ijarah Sukuk) to raise funds from many investors.","topicIds":["t15.3","t15.3.5.b","t15.4.cases"],"cautions":["True sale and real ownership","No issuer guarantee of fixed return"],"modeIds":["sukuk"],"pathway":"need","origin":["f1"]},"n-ujrah":{"id":"n-ujrah","title":"Ijarah of services (Ujrah)","why":"Hire of specified work for a wage/fee.","topicIds":["t11.1","t13.4.3"],"cautions":["Work and wage must be specified"],"modeIds":["ijarah"],"pathway":"need","origin":["f1"]},"n-jualah":{"id":"n-jualah","title":"Ju‘alah","why":"Reward for achieving a result that cannot be precisely specified in effort.","topicIds":["t13.4","t13.4.6"],"cautions":["No result, no reward"],"modeIds":["juaalah"],"pathway":"need","origin":["f1"]},"r-murabaha":{"id":"r-murabaha","title":"Murabaha","why":"You need a specific, already-identifiable asset and want the seller/bank to disclose its cost and profit openly.","structure":"The bank purchases the asset (or has its client purchase it as its agent), takes ownership/possession, then resells it to the client at the disclosed cost plus an agreed profit margin, usually on deferred payment.","keyConditions":["Bank must own and bear the risk of the asset before reselling it","Original cost and profit margin must be disclosed to the buyer","Price, once agreed, cannot later be changed even on late payment","Subject matter must exist, be owned, and be specifically identified"],"risks":["Customer refuses to purchase after the bank has bought the goods (mitigated with a binding promise and Hamish Jiddiyah)","Risk of executing Murabaha on goods the bank never actually possessed (Bai' al-'Inah concern)"],"chapter":9,"modeIds":["murabaha"],"pathway":"purpose","origin":["f2"]},"r-musawamah":{"id":"r-musawamah","title":"Musawamah","why":"You want an ordinary negotiated sale where the seller does not have to reveal cost.","structure":"Buyer and seller simply bargain and agree on a final price with no reference to the seller's cost; it can be a cash or deferred-payment sale.","keyConditions":["All general conditions of a valid Bai' still apply","Seller is not obliged to disclose cost or profit","Suitable when the seller cannot precisely ascertain its own cost, or does not wish to disclose a supplier discount"],"risks":["Less price transparency for the buyer than Murabaha","Benchmarking a 'fair' profit margin is harder than in Murabaha"],"chapter":9,"modeIds":["musawamah"],"pathway":"purpose","origin":["f2"]},"r-salam":{"id":"r-salam","title":"Salam","why":"A producer or seller needs cash now and can deliver a defined, fungible commodity at a fixed future date.","structure":"The buyer (bank) pays the full price in advance at the time of contract; the seller delivers a specified quantity and quality of a fungible good at an agreed future date and place.","keyConditions":["Full price must be paid on the spot","Subject matter must be fungible and precisely specified (quality, quantity, grade)","Delivery date and place must be fixed","Cannot be used for money/currency or a specific, non-fungible item"],"risks":["Seller's failure or delay in supplying the goods","Delivery of inferior-quality goods","Market risk to the bank in reselling the goods after delivery"],"chapter":10,"modeIds":["salam"],"pathway":"purpose","origin":["f2"]},"r-istisnaa":{"id":"r-istisnaa","title":"Istisna'a","why":"You need something custom manufactured or constructed and want flexible payment terms.","structure":"The bank (as buyer, or as manufacturer via a Parallel Istisna'a subcontract) commissions manufacture/construction to agreed specifications; price can be paid immediately, deferred, or in instalments tied to progress.","keyConditions":["Subject matter must always be something requiring manufacture","Contract becomes binding once the manufacturer starts work; before that, either party may cancel","Price and specifications must be clearly agreed","Delay penalties are permitted and treated as the purchaser's income"],"risks":["Delay or non-conformity of the finished item with specifications","Separate ownership risk in each leg of a Parallel Istisna'a arrangement","Manufacturer's performance risk"],"chapter":10,"modeIds":["istisnaa"],"pathway":"purpose","origin":["f2"]},"r-ijarah":{"id":"r-ijarah","title":"Ijarah","why":"You need temporary use of a nonconsumable asset without buying it outright.","structure":"The lessor retains ownership and its risks/expenses while transferring only the usufruct (right of use) to the lessee for an agreed rental over a defined period.","keyConditions":["Asset must be nonconsumable and its usufruct permissible","Rent must be clearly determined and cannot be charged before the lessee can benefit from the asset","Lessor bears ownership-related risk and major maintenance; lessee bears day-to-day running costs","Lease must be for a fixed, time-bound period"],"risks":["Lessor loses entitlement to rent if usufruct is lost through no fault of the lessee","Sub-lease and rent-review disputes if not clearly documented","Risk of the lease resembling interest-based financing if ownership risk isn't genuinely borne by the lessor"],"chapter":11,"modeIds":["ijarah"],"pathway":"purpose","origin":["f2"]},"r-ijarah-mbt":{"id":"r-ijarah-mbt","title":"Ijarah Muntahia-bi-Tamleek","why":"You want to use an asset now and transition to owning it at the end of the lease term.","structure":"A standard Ijarah lease runs alongside a separate, independent unilateral promise by the lessor to sell or gift the asset to the lessee at the end of the lease term.","keyConditions":["The lease and the ownership-transfer promise must be kept as two separate, independently enforceable contracts","The promise must be unilateral (binding the promisor, not both parties) to avoid 'two contracts in one bargain'","All standard Ijarah conditions (nonconsumable asset, defined rent, lessor bears ownership risk) still apply"],"risks":["Structuring risk if the sale/gift is embedded as a precondition of the lease itself","Disputes over asset condition/ownership transfer at end of term"],"chapter":11,"modeIds":["ijarah-muntahia-bi-tamleek","ijarah"],"pathway":"purpose","origin":["f2"]},"r-musharakah":{"id":"r-musharakah","title":"Musharakah","why":"Multiple parties want to invest capital and, optionally, jointly manage a business venture, sharing profit and loss.","structure":"All partners contribute capital (and may participate in management); profit is shared per any mutually agreed ratio, while loss must always be shared strictly in proportion to each partner's capital.","keyConditions":["Capital contributions should be clearly known/quantified","Profit ratio is freely agreed at contract execution; loss ratio must equal the capital ratio","All partners may take part in management unless restricted by agreement","Liability is normally unlimited unless otherwise agreed"],"risks":["Business/operational risk shared by all partners","Disputes over management authority or unauthorized commitments by a partner","Valuation risk when calculating periodic profit distributions"],"chapter":12,"modeIds":["musharakah"],"pathway":"purpose","origin":["f2"]},"r-mudarabah":{"id":"r-mudarabah","title":"Mudarabah","why":"A capital provider (Rabbul-mal) wants to invest with a skilled manager (Mudarib) without managing the business personally.","structure":"The Rabbul-mal provides capital; the Mudarib manages the business and trades with it. Profit is split per a pre-agreed ratio; financial loss is borne solely by the Rabbul-mal unless the Mudarib was negligent or dishonest.","keyConditions":["Rabbul-mal has no right to participate in management beyond monitoring","Profit ratio must be a proportion of realized profit, never a fixed sum or capital percentage","Financial loss falls entirely on the capital provider absent Mudarib misconduct","Sub-Mudarabah requires the Rabbul-mal's permission"],"risks":["Rabbul-mal bears all financial loss from normal business risk","Moral hazard / information asymmetry regarding the Mudarib's diligence","Difficulty verifying business performance until liquidation/settlement"],"chapter":12,"modeIds":["mudarabah"],"pathway":"purpose","origin":["f2"]},"r-diminishing-musharakah":{"id":"r-diminishing-musharakah","title":"Diminishing Musharakah","why":"You want to acquire full ownership of a fixed asset (like a house) gradually, or have a partner's ownership share bought out over time.","structure":"Bank and client become co-owners of the asset (Shirkatulmilk); the bank leases its share to the client for rent; the client periodically buys units of the bank's share per an agreed schedule, and rent reduces as the client's ownership grows.","keyConditions":["Partnership, lease, and each unit sale must be separate, independently enforceable contracts","In Shirkatulmilk (e.g. housing), a pre-agreed purchase-price schedule is permitted","In DM for trade/profit-earning ventures, unit prices must be based on valuation at the time of sale, not pre-fixed"],"risks":["Ownership-related risk shared jointly between partners on a pro rata basis","Valuation disputes when pricing units in a trade-based DM","Documentation risk if the three contracts are not kept independent"],"chapter":12,"modeIds":["diminishing-musharakah","musharakah"],"pathway":"purpose","origin":["f2"]},"r-tawarruq":{"id":"r-tawarruq","title":"Tawarruq","why":"You have a genuine, limited need for cash liquidity and are willing to buy a commodity on credit and sell it, to a third party, for spot cash.","structure":"The client buys a commodity from the bank on deferred payment, then sells it (directly or via an independent third-party sale) for cash, obtaining liquidity while owing the deferred price to the bank.","keyConditions":["The client must sell to a third party, not back to the original seller (to avoid Bai' al-'Inah)","All conditions of a valid, sequential sale (possession, independent contracts) must be met","Scholars advise limiting Tawarruq to unavoidable corporate liquidity needs, not routine consumer financing"],"risks":["Risk of resembling Bai' al-'Inah / disguised interest if structured carelessly","Systemic risk from wide, careless use, per the scholars the book cites","Compliance risk if commodity possession/ownership isn't genuine"],"chapter":13,"modeIds":["tawarruq"],"pathway":"purpose","origin":["f2"]},"r-caution-tawarruq":{"id":"r-caution-tawarruq","title":"Tawarruq (use with caution)","why":"Your liquidity need looks more like routine or consumer financing than an unavoidable corporate need.","structure":"Tawarruq is technically permissible by the majority view when properly structured, but the book notes that scholars advise it be used only for unavoidable, limited corporate liquidity needs and kept out of individual consumer financing wherever possible.","keyConditions":["Reconsider whether an asset-based mode (Murabaha, Ijarah, Diminishing Musharakah) can meet the same need instead","If Tawarruq is used, ensure genuine possession and a true third-party sale"],"risks":["Overuse creates systemic Shari'ah-compliance and reputational risk, per the scholars the book cites","Risk of the transaction collapsing into disguised interest if not properly structured"],"chapter":13,"modeIds":["tawarruq"],"pathway":"purpose","origin":["f2"]},"r-sukuk":{"id":"r-sukuk","title":"Sukuk (asset-backed securitization)","why":"You want to mobilize funds from many investors for a project via tradable certificates backed by real assets.","structure":"The originator transfers ownership of underlying assets (or a project) to a Special Purpose Vehicle (SPV), which issues Sukuk representing investors' undivided ownership shares; investors earn returns from the assets' cash flows/appreciation, not a fixed interest coupon.","keyConditions":["Sukuk must represent real, undivided ownership in tangible assets, usufruct, services, or a specific Shari'ah-compliant project (Ijarah, Salam, Istisna'a, Shirkah bases, etc.)","Mudarabah/Musharakah Sukuk may not guarantee capital or a fixed/percentage-of-capital return","For lease/receivable securitization, actual pro-rata ownership of the underlying asset must pass to Sukuk holders"],"risks":["Credit/bankruptcy, performance, asset/collateral, payment, and return-rate risks (per the book's risk-analysis categories)","Legal/regulatory risk from SPV structuring across jurisdictions","Market/liquidity risk in the secondary trading of Sukuk"],"chapter":15,"modeIds":["sukuk"],"pathway":"purpose","origin":["f2"]},"r-non-compliant-debt":{"id":"r-non-compliant-debt","title":"Not Shari'ah-compliant as described","why":"A certificate representing a pure debt/interest claim with no underlying real asset does not meet the Shari'ah bases for Sukuk.","structure":"This would function as a conventional interest-bearing bond, not a Sukuk — it falls outside AAOIFI's Shari'ah bases for investment Sukuk, which require ownership in tangible assets, usufruct, services, or a specified project.","keyConditions":["Reconsider structuring the issue on an Ijarah, Salam, Istisna'a, or Shirkah basis with real underlying assets","Ensure no guarantee of capital or fixed return is embedded"],"risks":["Such an instrument would reintroduce Riba and would not be recognized as Shari'ah-compliant Sukuk"],"chapter":15,"modeIds":[],"pathway":"purpose","origin":["f2"]},"r-takaful":{"id":"r-takaful","title":"Takaful","why":"You need protection against risk of loss (life or property) without the Riba, Gharar and Maisir the book identifies in conventional insurance.","structure":"Participants make donations (Tabarru') into a common fund (often structured as a Waqf); the fund pays out to members who suffer a loss, and the operator manages the fund/investments on a Mudarabah, Wakalah, or hybrid Wakalah-Mudarabah basis.","keyConditions":["Contributions are treated as donations (Tabarru'), not premiums bought against an unknown benefit","Funds must be invested only in Shari'ah-compliant avenues","In the model the book considers best, any underwriting surplus belongs to participants, distributed pro rata to contributions"],"risks":["Residual uncertainty within the group is minimized, not eliminated, by reserves and Qard al-Hasan from shareholders when needed","Model-specific issues in Mudarabah or Wakalah-Mudarabah Takaful structures (e.g. expense allocation)","Smaller risk pools may face higher volatility than large conventional insurers"],"chapter":16,"modeIds":["takaful"],"pathway":"purpose","origin":["f2"]}}});
